package org.forestear.node.device

/**
 * Auto-generated compatibility report, one Markdown file per phone model.
 *
 * Honesty rules:
 *  - capability facts come from the probe, not from assumptions;
 *  - benchmark numbers are printed only when they were actually measured;
 *  - recovery paths that were not exercised are printed as NOT RUN, never PASS.
 */
data class ReportCheck(
    val id: String,
    val title: String,
    val status: String, // PASS / WARN / FAIL / NOT RUN
    val detail: String,
)

object CompatibilityReport {

    fun build(
        profile: DeviceProfile,
        tier: TierPlan?,
        checks: List<ReportCheck>,
        recovery: List<RecoveryResult>,
        benchmarkMs: Map<String, Double> = emptyMap(),
        generatedUtc: String = profile.generatedUtc,
        oemProfile: OemProfile? = null,
    ): String = buildString {
        appendLine("# ForestEar compatibility report — ${profile.build.manufacturer} ${profile.build.model}")
        appendLine()
        appendLine("Generated: $generatedUtc  ")
        appendLine("App version: ${profile.appVersionName} (code ${profile.appVersionCode})  ")
        appendLine("Probe: `${profile.probeSource}`  ")
        appendLine("Profile file: `device_profile.json`")
        appendLine()
        appendLine("> This file is generated by the app from what the OS actually reported. " +
            "Anything the platform did not expose is listed as missing or unknown. " +
            "Recovery paths marked NOT RUN have not been exercised on this handset.")
        appendLine()

        appendLine("## Hardware")
        appendLine()
        appendLine("| Field | Value |")
        appendLine("|---|---|")
        appendLine("| Manufacturer / brand | ${profile.build.manufacturer} / ${profile.build.brand} |")
        appendLine("| Model / device / product | ${profile.build.model} / ${profile.build.device} / ${profile.build.product} |")
        appendLine("| SoC | ${profile.build.socManufacturer} ${profile.build.socModel} |")
        appendLine("| Android | ${profile.build.androidRelease} (API ${profile.build.sdkInt}) |")
        appendLine("| ABIs | ${profile.build.abis.joinToString(", ").ifBlank { "unknown" }} |")
        appendLine("| Cores | ${profile.build.cores} |")
        appendLine("| RAM | ${profile.build.ramTotalMb} MB total, ${profile.build.ramAvailableMb} MB available |")
        appendLine("| Free storage | ${profile.build.freeStorageMb} MB |")
        appendLine("| Emulator | ${profile.build.isEmulator} |")
        appendLine()

        appendLine("## Audio")
        appendLine()
        appendLine("Native output rate: ${profile.audio.nativeSampleRate} Hz; requested capture rate: " +
            "${profile.audio.requestedSampleRate} Hz; UNPROCESSED supported: ${profile.audio.unprocessedSupported}.")
        appendLine()
        if (profile.audio.inputs.isEmpty()) {
            appendLine("No input devices were enumerated.")
        } else {
            appendLine("| Input | Type | External | Rates (Hz) | Channels |")
            appendLine("|---|---|---|---|---|")
            profile.audio.inputs.forEach { input ->
                appendLine(
                    "| ${input.name.escape()} | ${input.typeLabel} | ${input.isExternal} | " +
                        "${input.sampleRates.joinToString(", ").ifBlank { "unknown" }} | " +
                        "${input.channelCounts.joinToString(", ").ifBlank { "unknown" }} |"
                )
            }
        }
        appendLine()
        appendLine("Effect descriptors: AGC=${profile.audio.agcAvailable}, " +
            "NS=${profile.audio.nsAvailable}, AEC=${profile.audio.aecAvailable}. " +
            "Availability is not the same as successful disablement; the capture status line " +
            "records what was actually turned off for the active session.")
        appendLine()

        appendLine("## Telephony, location, power")
        appendLine()
        appendLine("- Telephony: ${profile.telephony.hasTelephony}; SMS capable: ${profile.telephony.hasSms}; " +
            "SIM slots: ${profile.telephony.simSlots}; subscriptions: ${profile.telephony.subscriptions.size}")
        appendLine("- Default data sub: ${profile.telephony.defaultDataSubId}; default SMS sub: " +
            "${profile.telephony.defaultSmsSubId}; network: ${profile.telephony.networkType}")
        appendLine("- Location: manager=${profile.location.hasLocationManager}, GPS=${profile.location.hasGps}, " +
            "network=${profile.location.hasNetworkProvider}, fused=${profile.location.hasFusedProvider}, " +
            "fine=${profile.location.fineGranted}, coarse=${profile.location.coarseGranted}")
        appendLine("- Battery: ${profile.battery.percent}%, ${profile.battery.plugged}, " +
            "temp=${profile.battery.temperatureC?.let { "%.1f C".format(it) } ?: "unknown"}, " +
            "capacity=${profile.battery.capacityMah?.toString() ?: "unknown"}, " +
            "thermal API=${profile.battery.thermalApiAvailable} (${profile.battery.thermalLabel}), " +
            "removable=${profile.battery.removable}")
        appendLine()

        if (oemProfile != null) {
            appendLine("## OEM profile")
            appendLine()
            appendLine("Matched profile: **${oemProfile.displayName}** (`${oemProfile.id}`).")
            appendLine()
            appendLine(oemProfile.notes)
            appendLine()
            appendLine("Reference: ${oemProfile.dontkillmyappUrl}")
            appendLine()
        }

        appendLine("## Performance tier")
        appendLine()
        if (tier == null) {
            appendLine("No tier has been selected yet. Run Diagnostics → Benchmark.")
        } else {
            appendLine("- Selected tier: **${tier.tier.name}**")
            appendLine("- Models: ${tier.enabledModels.sorted().joinToString(", ")}")
            appendLine("- Hop: ${tier.hopS} s; anomaly every ${tier.m6Every.ifZero("disabled")}; " +
                "BirdNET duty ${tier.m8Duty.ifZero("disabled")}; streaming-only=${tier.streamOnly}")
            appendLine("- Reason: ${tier.reason}")
            if (tier.measuredPipelineMs.isFinite()) {
                appendLine("- Measured pipeline: %.2f ms/window (budget %.0f ms)"
                    .format(tier.measuredPipelineMs, tier.budgetMs))
            } else {
                appendLine("- Measured pipeline: not measured")
            }
            appendLine()
            if (benchmarkMs.isNotEmpty()) {
                appendLine("| Model | Mean ms |")
                appendLine("|---|---|")
                benchmarkMs.toSortedMap().forEach { (model, ms) ->
                    appendLine("| $model | ${"%.2f".format(ms)} |")
                }
                appendLine()
            }
        }

        appendLine("## Checks")
        appendLine()
        appendLine("| Check | Status | Detail |")
        appendLine("|---|---|---|")
        checks.forEach { c ->
            appendLine("| ${c.title.escape()} | ${c.status} | ${c.detail.escape()} |")
        }
        appendLine()

        appendLine("## Recovery paths")
        appendLine()
        appendLine("These are the paths that actually decide whether a phone survives as a node. " +
            "They must be run on the handset; the app records the result of each attempt.")
        appendLine()
        appendLine("| Path | Outcome | Detail | Recorded |")
        appendLine("|---|---|---|---|")
        val known = listOf(
            "kill_service" to "Service killed by the system / adb",
            "swipe_away" to "Task swiped from Recents",
            "reboot" to "Phone rebooted",
            "boot_receiver" to "Boot receiver started the service",
            "watchdog" to "Watchdog restarted the service",
            "screen_off" to "Screen off continuity",
            "mic_theft" to "Another app took the microphone",
        )
        for ((id, title) in known) {
            val result = recovery.firstOrNull { it.path == id }
            appendLine(
                "| ${title.escape()} | ${result?.outcome ?: "NOT RUN"} | " +
                    "${(result?.detail ?: "not exercised on this handset").escape()} | " +
                    "${result?.recordedUtc ?: "—"} |"
            )
        }
        val extra = recovery.filter { r -> known.none { it.first == r.path } }
        for (r in extra) {
            appendLine("| ${r.path.escape()} | ${r.outcome} | ${r.detail.escape()} | ${r.recordedUtc} |")
        }
        appendLine()

        if (profile.missing.isNotEmpty()) {
            appendLine("## Missing capabilities")
            appendLine()
            profile.missing.forEach { appendLine("- $it") }
            appendLine()
        }
        if (profile.warnings.isNotEmpty()) {
            appendLine("## Warnings")
            appendLine()
            profile.warnings.forEach { appendLine("- $it") }
            appendLine()
        }

        appendLine("## What this report does not claim")
        appendLine()
        appendLine("- It does not claim an on-phone accuracy figure. Detection accuracy was measured " +
            "on the Python evaluation set, not on this microphone.")
        appendLine("- It does not claim a recovery path works until the row says PASS.")
        appendLine("- It does not claim a missing capability exists; unknown is recorded as unknown.")
        appendLine()
    }

    fun fileName(profile: DeviceProfile): String {
        val slug = slug("${profile.build.manufacturer}_${profile.build.model}")
        return "compatibility_report_$slug.md"
    }

    fun slug(value: String): String {
        val cleaned = value.trim().lowercase()
            .replace(Regex("[^a-z0-9]+"), "_")
            .trim('_')
        return cleaned.ifBlank { "unknown_device" }
    }

    private fun Int.ifZero(replacement: String): String = if (this == 0) replacement else toString()
    private fun String.escape(): String = replace("|", "\\|").replace("\n", " ")
}
